// src/App.jsx
// Same routing logic as original (useState page navigation).
// Added: AuthProvider wraps everything, loading state on session restore.

import { useState } from "react";
import LoginScreen    from "./screens/LoginScreen";
import SignupScreen   from "./screens/SignupScreen";
import DashboardLayout from "./screens/DashboardLayout";
import { AuthProvider, useAuth } from "./context/AuthContext";
import "./index.css";

// Inner app — reads from AuthContext
function AppInner() {
  const { user, loading, logout } = useAuth();
  const [page, setPage]           = useState("login");
  const [prefillPhone, setPrefill] = useState("");

  // While restoring session from localStorage token, show a splash
  if (loading) {
    return (
      <div style={{
        minHeight: "100vh", display: "flex", alignItems: "center",
        justifyContent: "center", background: "#f0f7e8",
        fontFamily: "Poppins, sans-serif", color: "#004E00", fontSize: 16,
      }}>
        🌾 Loading…
      </div>
    );
  }

  // If user is already logged in (session restored from token), go straight to dashboard
  if (user && page === "login") {
    return <DashboardLayout onLogout={() => { logout(); setPage("login"); }} />;
  }

  const handleNavigate = (destination, params = {}) => {
    if (params.phone) setPrefill(params.phone);
    else setPrefill("");
    setPage(destination);
  };

  const handleLogout = () => {
    logout();       // clears JWT tokens
    setPrefill("");
    setPage("login");
  };

  if (page === "login") {
    return <LoginScreen onNavigate={handleNavigate} prefillPhone={prefillPhone} />;
  }

  if (page === "signup") {
    return <SignupScreen onNavigate={handleNavigate} />;
  }

  // home | live | logs | settings → all inside DashboardLayout
  return <DashboardLayout onLogout={handleLogout} />;
}

// Wrap with AuthProvider so all children can use useAuth()
export default function App() {
  return (
    <AuthProvider>
      <AppInner />
    </AuthProvider>
  );
}
